CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(100) NOT NULL, phone VARCHAR(30), role ENUM('ADMIN','MANAGER','STAFF','CUSTOMER') NOT NULL, active BIT NOT NULL);
CREATE TABLE auth_sessions (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, user_id BIGINT NOT NULL, refresh_hash VARCHAR(64) NOT NULL UNIQUE, expires_at DATETIME(6) NOT NULL, revoked BIT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE addresses (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, user_id BIGINT NOT NULL, recipient VARCHAR(100) NOT NULL, phone VARCHAR(30) NOT NULL, line1 VARCHAR(255) NOT NULL, line2 VARCHAR(100), city VARCHAR(100) NOT NULL, region VARCHAR(100) NOT NULL, postal_code VARCHAR(20) NOT NULL, country VARCHAR(80) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE categories (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, name VARCHAR(80) NOT NULL UNIQUE, slug VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE products (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, sku VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, description VARCHAR(5000) NOT NULL, price DECIMAL(12,2) NOT NULL, compare_at_price DECIMAL(12,2), category_id BIGINT NOT NULL, active BIT NOT NULL, featured BIT NOT NULL, specifications VARCHAR(2000) NOT NULL, FOREIGN KEY(category_id) REFERENCES categories(id), CHECK(price>0), CHECK(compare_at_price IS NULL OR compare_at_price>=price), INDEX idx_product_category_active(category_id,active));
CREATE TABLE product_images (product_id BIGINT NOT NULL, position INT NOT NULL, url VARCHAR(500), PRIMARY KEY(product_id,position), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE inventory (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, product_id BIGINT NOT NULL UNIQUE, quantity INT NOT NULL, low_stock_threshold INT NOT NULL, version BIGINT NOT NULL, FOREIGN KEY(product_id) REFERENCES products(id), CHECK(quantity>=0), CHECK(low_stock_threshold>=0));
CREATE TABLE orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, number VARCHAR(40) NOT NULL UNIQUE, customer_id BIGINT NOT NULL, status ENUM('PENDING','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED') NOT NULL, subtotal DECIMAL(12,2) NOT NULL, shipping DECIMAL(12,2) NOT NULL, total DECIMAL(12,2) NOT NULL, stock_allocated BIT NOT NULL, idempotency_key VARCHAR(80) NOT NULL, request_hash VARCHAR(64) NOT NULL, address_id BIGINT NOT NULL, FOREIGN KEY(customer_id) REFERENCES users(id), FOREIGN KEY(address_id) REFERENCES addresses(id), UNIQUE KEY uq_checkout(customer_id,idempotency_key), INDEX idx_order_date(created_at), INDEX idx_order_status(status));
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_name VARCHAR(160) NOT NULL, sku VARCHAR(80) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id), CHECK(quantity>0));
CREATE TABLE inventory_movements (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, product_id BIGINT NOT NULL, actor_id BIGINT, order_id BIGINT, delta INT NOT NULL, balance_after INT NOT NULL, reason VARCHAR(255) NOT NULL, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(actor_id) REFERENCES users(id), FOREIGN KEY(order_id) REFERENCES orders(id), INDEX idx_movement_product(product_id,created_at));
CREATE TABLE payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, order_id BIGINT NOT NULL UNIQUE, method ENUM('CARD','COD') NOT NULL, status ENUM('PENDING','PAID','FAILED','REFUNDED') NOT NULL, amount DECIMAL(12,2) NOT NULL, reference VARCHAR(50) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE payment_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, payment_id BIGINT NOT NULL, status ENUM('PENDING','PAID','FAILED','REFUNDED') NOT NULL, note VARCHAR(255) NOT NULL, FOREIGN KEY(payment_id) REFERENCES payments(id));
CREATE TABLE shipments (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, order_id BIGINT NOT NULL UNIQUE, tracking_number VARCHAR(50) NOT NULL UNIQUE, carrier VARCHAR(80) NOT NULL, status ENUM('CREATED','IN_TRANSIT','DELIVERED') NOT NULL, estimated_delivery DATE NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE order_status_history (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, order_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, status ENUM('PENDING','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED') NOT NULL, note VARCHAR(255) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE newsletter_subscriptions (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at DATETIME(6) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE);
